/**
 * @file Regenerates the Drizzle schema for Better Auth's tables
 * (`src/db/schema/auth.ts`) from the auth config, then applies the project's
 * database rules to it.
 *
 * Usage: `pnpm auth:schema` (run after changing Better Auth plugins or fields,
 * then `pnpm db:generate` for the migration).
 *
 * Rules applied to the generated file:
 * - IDs default to Postgres's time-ordered `uuidv7()` instead of random v4
 *   UUIDs, so new rows append to indexes instead of scattering.
 * - Timestamps are stored with time zone.
 * - JSDoc comments, as the lint rules require.
 */
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';

/** The generated schema file. */
const OUTPUT = 'src/db/schema/auth.ts';

/** Comment placed at the top of the generated file. */
const HEADER = `/**
 * @file Drizzle schema for Better Auth's tables (users, sessions, accounts,
 * verification tokens, two-factor settings and passkeys).
 *
 * Generated by \`pnpm auth:schema\`; don't edit by hand.
 */
`;

/**
 * Applies the project's rules to the generated schema source.
 *
 * @param source - The schema as generated by the Better Auth CLI.
 * @returns The adjusted schema source.
 */
function applySchemaRules(source: string): string {
  return (
    HEADER +
    source
      .replaceAll('pg_catalog.gen_random_uuid()', 'uuidv7()')
      .replace(/timestamp\("([a-z_]+)"\)/g, 'timestamp("$1", { withTimezone: true })')
      .replace(
        /^export const (\w+) = pgTable\(/gm,
        "/** Better Auth's `$1` table. */\nexport const $1 = pgTable(",
      )
      .replace(
        /^export const (\w+)Relations = relations\(/gm,
        '/** Relations of the `$1` table. */\nexport const $1Relations = relations(',
      )
  );
}

/**
 * Runs a command and stops the script if it fails.
 *
 * @param command - The executable.
 * @param args - Its arguments.
 */
function run(command: string, args: string[]) {
  execFileSync(command, args, { stdio: 'inherit' });
}

run('pnpm', [
  'exec',
  'auth',
  'generate',
  '--config',
  'src/lib/auth.ts',
  '--output',
  OUTPUT,
  '--yes',
]);
writeFileSync(OUTPUT, applySchemaRules(readFileSync(OUTPUT, 'utf8')));
run('pnpm', ['exec', 'eslint', '--fix', OUTPUT]);
